// ---------------------------------------------------------------------------
// Start van de testament-generatie.
//
// Zelfde jobmodel als de andere generatoren: de webhook antwoordt direct met
// een job_id en de workflow loopt daarachter door. Het renderen duurt hier maar
// een seconde — er komt geen model aan te pas — maar het jobmodel houden we
// aan zodat de webapp één manier van wachten heeft en er later een controlestap
// tussen kan zonder dat de webapp verandert.
//
// Verwacht multipart-form-data met één veld 'payload' (JSON-tekst).
// ---------------------------------------------------------------------------

const fs = require('fs');
const JOB_DIR = '/data/shared/jobs';
const BEWAARTERMIJN_MS = 24 * 60 * 60 * 1000;

// Een throw in een Code node levert bij responseMode=responseNode een leeg
// 200-antwoord op; verwachte fouten gaan daarom als data terug. De IF-node
// hierna splitst erop.
function mislukt(bericht) {
  return [{ json: { ok: false, error: bericht } }];
}

const body = $json.body || $json || {};
let payload;
try {
  payload = typeof body.payload === 'string' ? JSON.parse(body.payload) : (body.payload || body);
} catch (err) {
  return mislukt(`Kon payload niet lezen als JSON: ${err.message}`);
}

const personen = Array.isArray(payload.personen) ? payload.personen : [];
const testamenten = Array.isArray(payload.testamenten) ? payload.testamenten : [];
if (!personen.length) return mislukt('Geen cliëntgegevens meegestuurd.');
if (!testamenten.length) return mislukt('Geen testamenten meegestuurd.');
if (testamenten.length > 4) return mislukt('Hoogstens vier testamenten per keer.');

for (const [i, t] of testamenten.entries()) {
  const erflater = Number(t.erflater);
  if (!Number.isInteger(erflater) || erflater < 0 || erflater >= personen.length) {
    return mislukt(`Testament ${i + 1} verwijst naar een cliënt die niet bestaat.`);
  }
  if (!Array.isArray(t.geselecteerd) || !t.geselecteerd.length) {
    return mislukt(`Testament ${i + 1} heeft geen enkel blok geselecteerd.`);
  }
}

const nu = new Date();
const stempel =
  nu.getFullYear() +
  String(nu.getMonth() + 1).padStart(2, '0') +
  String(nu.getDate()).padStart(2, '0') + '_' +
  String(nu.getHours()).padStart(2, '0') +
  String(nu.getMinutes()).padStart(2, '0') +
  String(nu.getSeconds()).padStart(2, '0');

const referentie = String(payload.referentie || payload?.metadata?.dossier || stempel)
  .replace(/[^0-9A-Za-z_.-]/g, '_');
const jobId = `testament_${stempel}_${String($execution.id || 'x')}`
  .replace(/[^0-9A-Za-z_-]/g, '_');

fs.mkdirSync(JOB_DIR, { recursive: true });

// Oude jobbestanden opruimen; ze bevatten cliëntgegevens.
try {
  for (const naam of fs.readdirSync(JOB_DIR)) {
    if (!naam.endsWith('.json')) continue;
    const pad = `${JOB_DIR}/${naam}`;
    if (Date.now() - fs.statSync(pad).mtimeMs > BEWAARTERMIJN_MS) fs.unlinkSync(pad);
  }
} catch (_) {
  // Opruimen is best-effort; een nieuwe job mag er niet op stuklopen.
}

fs.writeFileSync(
  `${JOB_DIR}/${jobId}.json`,
  JSON.stringify({
    job_id: jobId,
    soort: 'testament',
    status: 'akte opmaken',
    fase: 1,
    referentie,
    aantal_testamenten: testamenten.length,
    resultaat: null,
    fout: null,
    gestart_op: nu.toISOString(),
    bijgewerkt_op: nu.toISOString(),
  }),
  'utf8'
);

const execId = String($execution.id || 'single').replace(/[^0-9A-Za-z_-]/g, '_').slice(0, 32);
const argsFile = `/tmp/n8n_args_testament_${execId}_${Date.now()}.json`;
fs.writeFileSync(
  argsFile,
  JSON.stringify({
    referentie,
    metadata: payload.metadata || {},
    herkomst: payload.herkomst || {},
    personen,
    testamenten,
    prijs_controle_cent: payload.prijs_controle_cent ?? null,
    blokken_bestand: `/data/shared/templates/aktes/${String(payload.soort || 'testament').replace(/[^a-z]/g, '')}.json`,
    kantoor_bestand: '/data/shared/kantoor.json',
  }),
  'utf8'
);

return [{ json: { ok: true, jobId, jobPad: `${JOB_DIR}/${jobId}.json`, argsFile, referentie } }];

// Leest de uitvoer van genereer_testament.py, zet het resultaat in het
// jobbestand en levert het aan de webapp. De HTTP-respons met het job_id is al
// veel eerder verstuurd; hier gaat niets meer over de lijn.
const fs = require('fs');

const start = $('Create Testament Job').first()?.json || {};
const cmd = $json || {};
const stdout = String(cmd.stdout || '');
const stderr = String(cmd.stderr || '');

function werkJobBij(velden) {
  let job = {};
  try {
    job = JSON.parse(fs.readFileSync(start.jobPad, 'utf8'));
  } catch (_) {
    // Jobbestand weg (handmatig opgeruimd?): dan schrijven we het opnieuw aan.
  }
  const nieuw = { ...job, ...velden, bijgewerkt_op: new Date().toISOString() };
  try {
    fs.writeFileSync(start.jobPad, JSON.stringify(nieuw), 'utf8');
  } catch (_) {
    // Niet kunnen bijwerken maakt de documenten niet ongeldig.
  }
  return nieuw;
}

function regel(naam) {
  const m = stdout.match(new RegExp(`^${naam}:\\s*(.+)$`, 'm'));
  return m ? m[1].trim() : '';
}

const succesPad = regel('SUCCESS');
if (!succesPad) {
  const fout =
    `Concept niet gegenereerd. stdout=${stdout.slice(0, 300)}; stderr=${stderr.slice(0, 300)}`;
  werkJobBij({ status: 'fout', fase: 2, fout, resultaat: null });
  return [{ json: { success: false, error: fout } }];
}

let documenten = [];
let offerte = null;
try { documenten = JSON.parse(regel('DOCUMENTS') || '[]'); } catch (_) { /* leeg laten */ }
try { offerte = JSON.parse(regel('OFFERTE') || 'null'); } catch (_) { /* leeg laten */ }

const basis = 'http://localhost:8080/output/';
const metUrls = documenten.map((d) => ({
  ...d,
  download_url: basis + d.bestandsnaam,
  preview_url: basis + String(d.bestandsnaam).replace(/\.docx$/i, '.html'),
}));

const waarschuwingen = stdout
  .split('\n')
  .filter((r) => r.startsWith('WAARSCHUWING: '))
  .map((r) => r.slice('WAARSCHUWING: '.length));

const eerste = metUrls[0] || {};
const resultaat = {
  success: true,
  mode: 'testament',
  referentie: start.referentie || '',
  // De vlakke velden wijzen naar het eerste concept, zodat consumenten die het
  // patroon van de andere generatoren volgen blijven werken. `documenten` is
  // additief en bevat alles, inclusief de offerte.
  filename: eerste.bestandsnaam || null,
  file_path: eerste.pad || null,
  download_url: eerste.download_url || null,
  preview_url: eerste.preview_url || null,
  documenten: metUrls,
  offerte,
  totaal_cent: offerte ? offerte.totaal_cent : null,
  lege_velden: Number(regel('LEGE_VELDEN') || 0),
  waarschuwingen,
};

const job = werkJobBij({ status: 'klaar', fase: 2, fout: null, resultaat });
return [{ json: job }];
